Before recreating Figure 4.4 in the book we will fit the cubic regression model. The model formulation in the book differs from the quap code, below we follow the code formulation.


\[
\begin{align}
h_i &\sim \operatorname{Normal}(\mu_i, \sigma) \\
\mu &=  \alpha + \beta_1x_i + \beta_2x^2_i \\
\alpha &\sim \text{Normal}(178, 20) \\
\beta_1 &\sim \text{Log-Normal}(0,1) \\
\beta_2 &\sim \text{Normal}(0,10) \\
\beta_3 &\sim \text{Normal}(0,10) \\
\sigma &\sim \operatorname{Uniform}(0, 50) \\
\end{align}
\]


/* Model 4.5 pp. 111
A cubic model
*/
data {
  int&lt;lower=0&gt; N;
  vector[N] h;
  vector[N] x;
  vector[N] x2;
  vector[N] x3;
} 
parameters {
  real a;
  real&lt;lower=0&gt; b1;
  real b2;
  real b3;
  real&lt;lower=0, upper=50&gt; sigma;
}
transformed parameters {
  vector[N] mu;
  // Vectorized transformed parameter
  mu = a + b1 * x + b2 * x2 + b3 * x3;

}
model {
  // Priors
  a ~ normal(178, 20);
  b1 ~ lognormal(0,1);
  b2 ~ normal(0,10);
  b3 ~ normal(0,10);
  sigma ~ uniform(0,50);
  // Likelihood
  h ~ normal(mu, sigma);
}




