Code
# Prepare predictor variables for plotting
pred &lt;- data.frame(x = seq(from = -2.5, to = 2, by = 0.1)) |&gt; 
  mutate(x2 = x^2, 
         x3 = x^3)


draws4.3 &lt;- fit4.3d$draws(format = "df")
draws4.5 &lt;- fit4.5$draws(format = "df")
draws4.6 &lt;- fit4.6$draws(format = "df")


# prob for intervals
lwr.prob &lt;- 0.045
upr.prob &lt;- 0.955


predictions &lt;- bind_rows(
  draws4.3 |&gt; 
  select(a, b,sigma, .chain:.draw) |&gt; 
  expand_grid(pred) |&gt; 
  rowwise() |&gt; 
  mutate(y_rep = rnorm(1, a + b * x, sigma)) |&gt; 
  ungroup() |&gt; 
  summarise(.by = x, 
            mu = mean(a + b * x), 
            lwr = quantile(a + b * x, lwr.prob), 
            upr = quantile(a + b * x, upr.prob), 
            pred.lwr = quantile(y_rep, lwr.prob), 
            pred.upr = quantile(y_rep, upr.prob))  |&gt; 
